-- universe-content.sql
-- Single source of truth for all keynor-core universe content data.
-- Generated by Siegmund on request. Applied manually by the user.
--
-- Target tables: maps, eras, map_eras, characters, character_categories,
--   places, place_categories, factions, faction_categories, items,
--   item_categories, events, event_categories, lore, lore_categories,
--   entity_links, universe_entity_images, archetypes, signs
--
-- Excluded: users, oauth2_* (environment-specific, never in scope)
--
-- ⚠  Destructive: TRUNCATE removes all existing universe content before reinserting.
-- ⚠  Apply only after Flyway migrations are fully up to date (V1–V12 at minimum).
-- ⚠  NOT idempotent — do not apply twice on the same database.
-- ⚠  Requires user authorization before execution. Agents never run this directly.
--
-- How to apply:
--   psql -U keynor -d keynor_core -f src/main/resources/db/seed/universe-content.sql
--
