INSERT INTO maps (id, name, map_type, image) VALUES ('omniverse', 'The Omniverse', 'ABSTRACT', '');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('73192c9b-4b7f-45aa-93d4-cbd65026149e', 'Consecration of the Aleph and the Twelve Amets', 2, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.126235+00', '2026-06-23 18:54:04.126235+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('49187d39-6121-44b9-8477-f19e16fac16b', 'Era of Vestiges', 3, 'ERA', NULL, 'The oldest era of the temporal world, predating the creation of matter. In a yet-nonexistent universe, vestiges of a previous world drift adrift, ready for a new story.', '2026-06-23 18:54:04.13818+00', '2026-06-23 18:54:04.13818+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1a3a86db-9f36-4c9b-9509-1346576efdaa', 'Crash of the Prima Airship into the Sun', 4, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.151342+00', '2026-06-23 18:54:04.151342+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('47eb040e-b0d3-492a-8817-525a91705240', 'Era of Glimpses', 5, 'ERA', NULL, 'Beneath a mountain, the first concepts emerge.', '2026-06-23 18:54:04.164302+00', '2026-06-23 18:54:04.164302+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('b8b2d895-402d-4a88-a689-6b418ed0384c', 'Dot''s Escape', 6, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.368255+00', '2026-06-23 18:54:04.368255+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('733fa7c5-700d-418e-bcdd-64afe020bf3f', 'Era of the Unpronounceable', 7, 'ERA', NULL, 'Concepts begin to take shape; different peoples spread beneath the earth. An era defined by the conflict between individuation and union.', '2026-06-23 18:54:04.38277+00', '2026-06-23 18:54:04.38277+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('2c26e128-ea8d-4910-9d2d-9de56aca40cf', 'Victory of the People of Symbols', 8, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.399434+00', '2026-06-23 18:54:04.399434+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('af4bc3ba-5848-4c59-bceb-576f5528f939', 'Era of Symbols', 9, 'ERA', NULL, 'An empire of unpronounceable concepts emerges, refusing to accept divine authority.', '2026-06-23 18:54:04.418364+00', '2026-06-23 18:54:04.418364+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('98706f60-12d5-40a0-8291-ecfa3dfb9d5c', 'Death of Jung Blackheart, Chief Resister', 10, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.450108+00', '2026-06-23 18:54:04.450108+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('ec1a7fa1-7316-47df-9689-f7a65359cc87', 'Era of Forms', 11, 'ERA', NULL, 'Concepts cross the Black Lake and begin to take shape before the light of truth.', '2026-06-23 18:54:04.462402+00', '2026-06-23 18:54:04.462402+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1cabbeb8-bcc3-44e1-8367-c193a38e619b', 'Discovery of Singisdonia', 12, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.47631+00', '2026-06-23 18:54:04.47631+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('7723f15f-18cc-43f9-81e4-72ee47f5cee3', 'Era of Singisdonia', 13, 'ERA', NULL, 'A time of light and evolution in the sacred city.', '2026-06-23 18:54:04.489599+00', '2026-06-23 18:54:04.489599+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('7315666c-2840-4635-980c-ec4d138f9c82', 'Attack of the Red King', 14, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.500854+00', '2026-06-23 18:54:04.500854+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('f583b008-820b-4a1a-8f41-35f90725042e', 'Era of Monads', 15, 'ERA', NULL, 'Concepts now migrate in search of another home, learning to grow on their own.', '2026-06-23 18:54:04.515353+00', '2026-06-23 18:54:04.515353+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1ede2bc9-af3b-4b72-83ce-f041a3d3a78c', 'Death of Teo', 16, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.52704+00', '2026-06-23 18:54:04.52704+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('8c57f579-e96a-41e4-821e-ee325c91384a', 'Era of the Platiad', 17, 'ERA', NULL, 'Concepts migrate into the Black Lake, and an era of intellect prevails.', '2026-06-23 18:54:04.731718+00', '2026-06-23 18:54:04.731718+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('d4509309-000e-4aaa-8640-d0d19425b846', 'Creation of the Material World', 18, 'POINT', 'MAJOR', NULL, '2026-06-23 18:54:04.746165+00', '2026-06-23 18:54:04.746165+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('2f0b14b1-2db2-4b78-a15b-d91b9344c26b', 'Era of Matter', 19, 'ERA', NULL, 'First semi-material beings shaped by the first particles.', '2026-06-23 18:54:04.75899+00', '2026-06-23 18:54:04.75899+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('05385230-9ee9-4840-9d23-1dbe20448579', 'Emergence of Mineral, Plant and Fungal Life', 20, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.774477+00', '2026-06-23 18:54:04.774477+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('0d158843-7145-460d-b504-ca8b31e7d162', 'Era of Life', 21, 'ERA', NULL, 'Formation of planets with autonomous beings.', '2026-06-23 18:54:04.786349+00', '2026-06-23 18:54:04.786349+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('5bdd7aef-132f-4e8a-b0d2-aa007464bbad', 'Emergence of Arthropod and Fish Life', 22, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.800177+00', '2026-06-23 18:54:04.800177+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1cef56ea-c063-423d-8116-02abd1b4ee17', 'Era of Elements', 23, 'ERA', NULL, 'Different planets with different natures, each representing different forces of nature.', '2026-06-23 18:54:04.812994+00', '2026-06-23 18:54:04.812994+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('a677296c-c0df-4012-a186-db612a55e39b', 'Emergence of Amphibians, Reptiles and Birds', 24, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.827346+00', '2026-06-23 18:54:04.827346+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('4a645394-65ca-4cba-a559-93762db9122a', 'Era of Footprints', 25, 'ERA', NULL, 'Change of environment and the emergence of dragons.', '2026-06-23 18:54:04.841227+00', '2026-06-23 18:54:04.841227+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('16defba8-7ca4-4d44-ad21-187cfb5066bf', 'Emergence of Mammals', 26, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.856265+00', '2026-06-23 18:54:04.856265+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('a5218652-50e5-4a59-8730-befe8589d2cf', 'Era of Wrath', 27, 'ERA', NULL, 'Continuation of the evolution of nature''s species.', '2026-06-23 18:54:04.868021+00', '2026-06-23 18:54:04.868021+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('a30b6eb5-4306-4bb6-8a83-908c4baa1d74', 'First Conscious Beings', 28, 'POINT', 'MAJOR', NULL, '2026-06-23 18:54:04.880869+00', '2026-06-23 18:54:04.880869+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('79f695b4-dd5d-468c-8040-8dd8acecd700', 'Era of the Pristine', 29, 'ERA', NULL, 'The world comes to be dominated by semi-divine beings.', '2026-06-23 18:54:05.083278+00', '2026-06-23 18:54:05.083278+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('2d7e9464-281f-4d01-a27c-0cba48fe8ff7', 'Rebellion of the Pristine', 30, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.096601+00', '2026-06-23 18:54:05.096601+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('bbfd36f0-8c02-414b-bf65-6377c9cd6d45', 'Era of Platinum', 31, 'ERA', NULL, 'Magic becomes centralised in a single city. Around the world, peoples wither.', '2026-06-23 18:54:05.107687+00', '2026-06-23 18:54:05.107687+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('5d838a34-2657-437d-bbb2-22370f390685', 'Fall of the City of Platinum', 32, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.120384+00', '2026-06-23 18:54:05.120384+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1096732a-5c98-48b1-85af-25f5e70580e6', 'Era of War', 33, 'ERA', NULL, 'The first nomadic peoples begin to unite and confront one another in a great war.', '2026-06-23 18:54:05.13198+00', '2026-06-23 18:54:05.13198+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('b0719d9d-640c-4daa-b047-1161ee9f07e1', 'The Cosmic Rifts Open', 34, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.14465+00', '2026-06-23 18:54:05.14465+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('d89ab35d-6b25-431e-95c4-7d0ae419d84f', 'Era of Heroes', 35, 'ERA', NULL, 'Great civilisations arise, and their heroes alongside them.', '2026-06-23 18:54:05.155195+00', '2026-06-23 18:54:05.155195+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('bae723a0-25e2-464c-a953-482ff99a1b4d', 'The Cosmic Rifts Close', 36, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.169088+00', '2026-06-23 18:54:05.169088+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('e54477b9-c9f8-4c51-9bf6-41d3802daf3b', 'Era of Magic', 37, 'ERA', NULL, 'Magic is used ever more recklessly. Segregation between peoples grows. Monarchies begin to fall.', '2026-06-23 18:54:05.180959+00', '2026-06-23 18:54:05.180959+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('a315a026-5488-4823-a1e6-b6c1c20238d8', 'Reopening of the Cosmic Rifts', 38, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.19475+00', '2026-06-23 18:54:05.19475+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('b33d7a47-cf46-4aa1-a6c5-b7527ec0de37', 'Era of Enlightenment', 39, 'ERA', NULL, 'The world begins to perceive the dangers of magic. Inquisition movements and technological research emerge.', '2026-06-23 18:54:05.206857+00', '2026-06-23 18:54:05.206857+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('d8d07906-b053-4eaf-9cad-ebc71a3d2fc3', 'End of Magic', 40, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.417734+00', '2026-06-23 18:54:05.417734+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('ebd3f220-f0bb-4073-a6f9-ed790e245679', 'Era of Artefacts', 41, 'ERA', NULL, 'Ancient artefacts still hold magical power and are sought by all as sources of strength.', '2026-06-23 18:54:05.622571+00', '2026-06-23 18:54:05.622571+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('d96d7190-b5cd-415b-95c5-fe42b28bf2b7', 'Establishment of the New Technological Order', 42, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.6372+00', '2026-06-23 18:54:05.6372+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('2eff7424-b158-43f9-a8a7-8992b3042295', 'Era of Law', 43, 'ERA', NULL, 'The study of military armament takes off, and a new wave of conquest begins among the most advanced nations.', '2026-06-23 18:54:05.651498+00', '2026-06-23 18:54:05.651498+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('34e4d7e0-d540-4079-923a-9f88803e2488', 'Emergence of Robotics, Electronics and Programming', 44, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.665055+00', '2026-06-23 18:54:05.665055+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('fe965866-a03a-4287-b4a8-b6d9eac9acb8', 'Era of Technology', 45, 'ERA', NULL, 'The world becomes completely dominated by technology.', '2026-06-23 18:54:05.683915+00', '2026-06-23 18:54:05.683915+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('34ca791f-6c98-4262-87d7-4b8abf13f328', 'Machine Rebellion', 46, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.695639+00', '2026-06-23 18:54:05.695639+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('13bd8972-a1c3-4e37-82b1-6f05e4040566', 'Era of Encounters', 47, 'ERA', NULL, 'Several civilisations are destroyed; others advance to the level of interplanetary travel.', '2026-06-23 18:54:05.708094+00', '2026-06-23 18:54:05.708094+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('83d1b21c-8399-43e3-99dc-0068d116c9a8', 'Intergalactic Catastrophe', 48, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.719254+00', '2026-06-23 18:54:05.719254+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('ff3d5bed-6438-4fdb-8919-0a41250ff71e', 'Era of Dust', 49, 'ERA', NULL, 'The world lives in a post-apocalyptic scenario; lack of resources brings society ever closer to its end.', '2026-06-23 18:54:05.732025+00', '2026-06-23 18:54:05.732025+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('659fdc07-604a-46b1-aa0e-133d7e54e5b8', 'The War of Hexagons Begins', 50, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.742603+00', '2026-06-23 18:54:05.742603+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('fd791fd4-6951-4fa8-957e-5979bff9427f', 'Era of Death', 51, 'ERA', NULL, 'The world is beset by constant conflict and marches toward its end.', '2026-06-23 18:54:05.914423+00', '2026-06-23 18:54:05.914423+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('f4f343d5-9208-45f9-b7d4-3debe69443da', 'End of Mortals', 52, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.928631+00', '2026-06-23 18:54:05.928631+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('48ed4b49-b7b5-4d4b-9715-00dcaa819209', 'Primordial Era', 1, 'ERA', NULL, 'The age before the material world came into being — a time of pure essence, divine forces, and the foundation upon which all existence would be built. No navigable world exists here; only the infinite.', '2026-06-23 18:54:04.047617+00', '2026-06-24 02:31:11.341815+00');
INSERT INTO map_eras (map_id, era_id) VALUES ('omniverse', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('b3e2c1d4-f5e6-4a7b-8c9d-0e1f2a3b4c5d', 'Omnia', 'The final word of all things, Omnia stands at the uttermost edge of becoming — goddess of totality, dwelling in a perfection no mortal thought has reached. She is not worshipped as one among many. She is acknowledged as the bound no eye can see past, the point at which existence stops and the unimaginable begins.', '## Omnia
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('988bdd8a-04a5-4e34-9857-f72918bec3a0', 'Ani', 'Ani, the Firstborn and the Primordial, is the god of unity itself — all existence pressed into a single, indivisible form, genderless and absolute. He is not approached as a power among powers, but as the seed from which division first became possible. Wherever he walks, it is said, the world takes root anew in his wake.', 'Ani is the god of unity — of singularity itself. He is called the Firstborn, the Primordial, for he is the representation of all existence pressed into a single, indivisible concept. He is at once everything and one: the totality of being folded into a solitary form.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('e5a5f4d2-ca44-45f1-a9b2-5cce46e69e30', 'Hexas', 'The goddess of Union and the Protection of Family, daughter of Tetros. Where her father endures alone, Hexas draws the circle that makes separation unnecessary — the deity of what remains after passion settles: the shared meal, the familiar face, the threshold crossed together.', 'Hexas is the goddess of number six, daughter of Tetros. She is the deity of union and of the protection of family and loved ones, and she bears her father''s gift for endurance without his isolation. Where Tetros stands alone, immovable, Hexas draws the circle that makes separation unnecessary. Her symbol is a hexagon ringed with circles at every vertex — each node distinct, each one touching two others, no point left without a neighbor.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('51a8d026-d237-40c1-8190-36d2a19f6b3c', 'Octo', 'The god of Eternal Growth and Evolution, son of Tetros. Patient where his father is still, Octo teaches that nothing truly grows in a straight line — it accumulates, folds back on itself, and begins again with more than it left with. His symbol is the double loop: the infinite path that always returns.', 'Octo is the god of number eight, son of Tetros. He is the deity of Eternal Growth and Evolution — a pairing that might seem to sit uneasily with his father''s still, immovable nature, until one understands that growth, too, can be patient. Octo does not rush. He does not surge. He accumulates.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('77db03b6-11a9-43ac-a96b-8a132f934622', 'Enea', 'The goddess of Worlds, Kingdoms, and Planets — one of the most expansive deities in scope. Enea does not notice individual valkani; she notices civilizations. She notices when worlds rise and when they go dark. Her domain is every world that turns beneath a sun.', 'Enea is the goddess of number nine, daughter of Trios. She is the divinity of Worlds, of Kingdoms, and of Planets — of every space vast enough to contain multitudes and complicated enough to sustain its own history. She is, by any measure, one of the most expansive of the gods in sheer scope. What she holds within her domain is not a single land or a single people, but every world that turns beneath a sun.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('173033ed-fd0d-4c11-8f63-26667ae2e93b', 'Deca', 'The goddess of Completeness and Reward, daughter of Tetros. Deca does not grant gifts — she returns them. What a valkani has given to the world in patience, discipline, and honest effort, she reflects back in full. Her judgment is exact, and she is the feeling of a thing, at last, being whole.', 'Deca is the goddess of number ten, daughter of Tetros. She is the deity of Completeness and of Reward — the one who arrives at the end of things, when the labor is done and the account can finally be settled. She is, in the truest sense, the goddess of the deserved.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('3c6dd2ab-b540-41a4-a4ad-2bca5e5f761c', 'Imaws', 'Imaws is the executive half of the oldest union in creation — the god who gives form to what his beloved Ælime sets in motion. If she is the impulse that wants to become, he is the hand that writes it into law. Together they fathered the Amets, the first concepts to drift through the primordial eternity, and from their twelve chosen children came every wonder and every wound the world would come to know. Imaws himself keeps to quiet, untouched places — the heart of old forests, the high silence of the mountains, the hollow behind a waterfall — a man with tired, forest-colored eyes who has been writing the world for longer than the world has existed.', 'Beneath Omnia, it is taught, there fall away a dohundred — one hundred and forty-four — layers of celestial heaven, and every one of them brims with gods past description: beings so vast and so strange that no mortal tongue has ever fixed a true name to a single one of them, and every one of them incomprehensibly powerful. And beneath all of that, deeper than the deepest of those dohundred heavens, the foundation holds two names only: Imaws, and Ælime.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('20744386-efc6-474d-aef6-27d7c4b8af33', 'Ælime', 'Ælime is the driving half of the oldest union in creation — the restlessness that wants to become, the spark that Imaws, her eternal counterpart, then gives shape and law. Her beauty is exotic and impossibly inspiring, and it is said a single glimpse of her is enough to lift joy into the heart of anyone who sees her; her mind, just as remarkable, can unravel any problem and settle any chaos into harmony. Together with Imaws she fathered the Amets, the first concepts to drift through the primordial eternity, and from their twelve chosen children came every wonder and every wound the world would come to know. Ælime herself is drawn to wherever life gathers loudest — the hottest shorelines, the most brightly lit cities, the most crowded festival — a woman with long, curling red hair, dressed as delicately as she is dazzlingly, who has been the pulse beneath the world since before the world had a pulse of its own.', 'Beneath Omnia, it is taught, there fall away a dohundred — one hundred and forty-four — layers of celestial heaven, and every one of them brims with gods past description: beings so vast and so strange that no mortal tongue has ever fixed a true name to a single one of them, and every one of them incomprehensibly powerful. And beneath all of that, deeper than the deepest of those dohundred heavens, the foundation holds two names only: Imaws, and Ælime.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('17373f6f-78c4-4621-858d-b1c1f1479704', 'Aleph', 'The God of Consciousness, foremost of the alephs and bearer of the Lantern of True Light. What his lantern’s light touches is what the valkani are able to perceive. Chosen among the twelve Amets by Imaws and Ælime, he stands at the center of Aniannoth’s mythology in the Primordial Era.', 'Among all the Amets, it is said that none is more blessed than Aleph. Many hold that he was the favored one among the twelve chosen of Imaws and Ælime. For this reason, it is said, he was gifted the Lantern of True Light. Others call this a biased opinion. They claim that all the Amets were gifted in equal measure, and that the lantern only seems the finer gift to us because we alone are capable of understanding it, where the others remain beyond our grasp. Whatever the truth, it is certain that Aleph stands among the most important gods in the whole mythology of Aniannoth. He is, too, the figure at the very center of the tale that unfolded across the Primordial Era.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('972854ca-dffb-4a2e-b7bc-759bd8bcb3a0', 'Duo', 'Duo, the god of Duality, is the firstborn child of Ani and Zςanser — a being split perfectly in two, opposite in color, temperament, and gaze, who wields twin swords capable of joining into one to cleave anything into its perfect opposite.', 'Duo, the god of Duality, closely resembles his father, Ani. He too presents himself with serenity, in a state of completeness. He too contains both genders within him. He too carries the harmony of all things.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('a37320ee-057a-4a33-8fda-82956761ab38', 'Pentos', 'The god of Spirituality and Religion, son of Trios. Pentos answers when the lost lift their eyes and ask if anything is listening — offering not answers, but the capacity to keep searching. His five-pointed star reaches outward from a center that does not move.', 'Pentos is the god of number five, son of Trios, and the divine embodiment of Spirituality and Religion. He is the keeper of the sacred — the force that answers when the valkani, lost in body or in soul, lift their eyes and ask if anything is listening. And something, always, is. Pentos radiates a power that those in his presence find difficult to describe afterward. It does not oppress. It illuminates. His symbol is a five-pointed star, each arm reaching outward from a center that does not move.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('c3fe20e2-722e-488e-bf4d-185fd024e900', 'Zςanser', 'Zςanser, often wrongly called the Goddess of Nothing, is in truth an absence — the one thing that does not belong to the totality of all existence. She dwells within a lake of black, frigid water of her own making, at once sinking through its depths and walking upon its surface. Grey and colorless but for her crystalline green eyes, she is the matrix of infinite potential from which all creation is endlessly carved, fleeing eternally from the burden of being drained into existence.', 'Zςanser is sometimes, and wrongly, called the Goddess of Nothing. But she is not nothing — she is an absence, and even nothingness belongs to the totality of all things, while she alone does not.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('76d64fa7-b226-4fe7-a65c-3db0f683b2c9', 'Tetros', 'The god of Stability and Balance, presiding over health, longevity, and temperance. Eternally seated in lotus, Tetros extends his immutable blessing only to those who have released the compulsion to grasp and conquer. His four arms are folded in meditation — not weakness, but strength that has chosen its own stillness.', 'Tetros is the god of Stability and of Balance. He presides over health, over longevity, and over temperance — the quiet art of knowing when enough is enough. He is found eternally seated in the lotus posture, still as stone, solid as a mountain that has never needed to justify its own weight. He asks nothing of those who approach him. He simply endures, and in his endurance he offers support to all who come seeking peace.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('e5c8fc7d-1128-40ea-8da3-eb93ebcd56d5', 'Unixia', 'The goddess of the Union between the Material and Spiritual Worlds, daughter of Trios. Unixia does not reconcile the two worlds — she moves between them, and in moving makes transit possible for others. Her devotees are mystics and those who have brushed against something they could not explain, and reached toward it.', 'Unixia is the goddess of number eleven, daughter of Trios. She is the deity of the Union between the Material and Spiritual Worlds — the living seam between what can be touched and what can only be felt. Eleven exceeds the familiar ten. It crosses a threshold. And Unixia, born of chaos and movement, is precisely that crossing.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('32168a53-162c-4f6a-9fb9-8b3fd4cb3988', 'Trios', 'The divinity of Chaos and Movement — the restless force that refuses to let the world settle into itself. Trios holds that any balance of perfect opposites breeds only deadlock, and that a third disruptive element is needed to set true evolution in motion. Patron of beasts and instinct, he bears a bronze trident and three eyes, the third of which perceives reality stripped of all illusion.', 'Trios is the divinity of Chaos and of Movement. He is the restless energy that challenges stability in favor of evolution — the force that refuses to let the world settle into itself. To the devotees of Trios, comfort is a curse. It breeds stagnation. It breeds conformity. It is not rest, but slow death.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('19c8770d-517e-4bf9-8f52-d14878a71954', 'Hecta', 'The mistress of Magic and Mysticism, daughter of Trios. She appears differently to each who encounters her, but every account shares the same sensation: standing before something immense that could unmake the air around them. She is not cruel. She simply is, and the world arranges itself accordingly.', 'Hecta is the goddess of number seven, daughter of Trios, and the mistress of Magic and Mysticism. Those who study the arcane speak her name with care. Not out of fear, precisely — though fear is present — but out of the awareness that she is listening, and that she is vast, and that the distance between her attention and her power is very small.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('62ded67a-3f6b-4671-a138-2b9beb4c5f07', 'Trixia', 'The shadow of Dixia and goddess of Imperfection and Particularity. Where her sister holds up the horizon as a destination, Trixia plants her feet in the ground and refuses to look that far — arguing that perfection is not merely unattainable but undesirable, for a thing that is absolute and complete has ceased. And yet, in her tireless effort to contradict Dixia, she has perhaps become nothing more than the other face of the same coin.', 'Trixia is the shadow of Dixia. She is the goddess of Imperfection and of Particularity — the deity who rules not over an idealized kingdom at the end of a road, but over the world as it is found: cracked, uneven, and alive. Where her sister holds up the horizon as a destination, Trixia plants her feet in the ground and refuses to look that far.
INSERT INTO characters (id, name, summary, body, status, created_at, updated_at, timeline_founded_era_id, timeline_destroyed_era_id) VALUES ('01ef16c4-09e2-40f3-9416-731d69f798b2', 'Dixia', 'The goddess of Perfection and Harmony, born from the union of Trios and Tetros — from Chaos and Stability, from Movement and Order. She does not preach forgiveness; she teaches dialogue and understanding, the patient work of returning every conflict to its most fundamental principle. Perfection is her destination, not her home: she walks the road ahead of her followers, close enough to give direction, too far to be touched.', 'Dixia is the goddess of Perfection and Harmony. She is, by her very nature, a prodigy — a miracle that should not exist. She was born from the union of Trios and Tetros: from Chaos and from Stability, from Movement and from Order, from the two forces that press against each other at the foundation of all things. And yet, from that meeting, she rose. Not as a compromise between them, but as proof that their apparent opposition was never absolute.
